import {previewSVG} from './discovery.js';
import {previewKind} from './discovery-previews.js';
import {diagram,scenes} from './visual-lessons.js';
import {editionFor} from './resource-editions.js';
import {courseLanguage} from "./content-language.js";
import { primaryCourses } from './catalogue-data.js';
import { assetHref } from './data-loader.js';
import { chapterSequencePage, mountChapterSequence } from './chapter-sequence.js';
import {enrichment} from './enrichment-data.js';
import { resourceCatalog } from './resources-data.js';
import { guides } from './learning-content.js';
import { icon } from './icons.js';
export {resourceCatalog};
const P=(fr,en)=>[fr,en];
const E=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const courses=Object.fromEntries(primaryCourses.map(c=>[c.id,c.title]));
const kinds={chapter:P('Chapitre élève · cours, activités et exercices','Student chapter · lessons, activities and exercises'),teacher:P('Édition professeur · corrections et conseils','Teacher edition · solutions and guidance'),fluency:P('Automatismes · fiche élève','Fluency · student worksheet'),'fluency-solutions':P('Automatismes · corrigé','Fluency · solutions')};
const tabs={understand:P('Comprendre','Understand'),experiment:P('Expérimenter','Experiment'),practice:P('S’entraîner','Practise'),documents:P('Documents','Documents')};
let filter='',query='';
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function matchingChapters(course,search){const q=normalize(search.trim());return resourceCatalog.chapters.filter(c=>(course==='all'||c.course===course)&&(!q||normalize([...c.title,c.course,c.topic].join(' ')).includes(q)));}
export function matchingSupplements(course,search){const q=normalize(search.trim());return resourceCatalog.supplements.filter(c=>(course==='all'||c.course===course)&&(!q||normalize([...c.title,c.course,c.kind].join(' ')).includes(q)));}
function supplementCards(items,t){return items.length?`<div class="course-supplements"><h3>${t(P('Banques d’exercices & préparation','Exercise banks & preparation'))}</h3>${items.map(c=>c.files[0].kind==='teacher'?`<details class="supplement-card"><summary>${E(t(c.title))}</summary>${fileLink(c.files[0],t(P('Ouvrir le document professeur','Open the teacher document')))}</details>`:`<details class="supplement-card"><summary>${E(t(c.title))}</summary>${fileLink(c.files[0],t(P('Version élève','Student version')))}<details><summary>${t(P('Version professeur / corrections','Teacher version / solutions'))}</summary>${fileLink(c.files[1],t(P('Ouvrir la version professeur','Open the teacher version')))}<p class="document-meta">${t(P('Les versions peuvent inclure des variantes différentes : compare les énoncés.','The editions may contain different variants: compare the questions.'))}</p></details></details>`).join('')}</div>`:'';}
function row(href,no,title,meta,id,t){const seen=id&&progress.seen.has(id);return `<li><a class="row" href="${href}" ${id?`data-chapter="${id}"`:''}><span class="row-no">${no}</span><span class="row-main"><span class="row-title">${E(title)}</span><span class="row-meta">${E(meta)}</span></span>${seen?`<span class="row-seen" title="${t(P('Déjà ouvert','Opened before'))}">${icon('check',16)}<span class="sr-only">${t(P('Déjà ouvert','Opened before'))}</span></span>`:''}${icon('caret-right',18)}</a></li>`;}
function workshopCards(t){const q=normalize(query.trim());const found=enrichment.filter(p=>!q||normalize([...p.title,...p.prerequisites,...p.level].join(' ')).includes(q));return found.length?`<details class="group workshops" ${q?'open':''}><summary>${t(P('Ateliers & approfondissements','Workshops & enrichment'))}<span>${found.length}</span></summary><p class="group-note">${t(P('Une méthode, quatre exercices progressifs et un problème de synthèse, avec solutions séparées. Fichiers FR et EN.','A method, four progressive exercises and a synthesis problem, with separate solutions. FR and EN files.'))}</p><ol class="rows">${found.map(p=>row(`#library/explore-${p.id}`,String(enrichment.indexOf(p)+1).padStart(2,'0'),t(p.title),t(p.level),'',t).replace('class="row"','class="row enrichment-card"')).join('')}</ol></details>`:'';}
const tabLabels=courses;
const progress={seen:new Set(),last:''};
const kb=(b,t)=>`${Math.max(1,Math.round(b/1024))} ${t(P('Ko','KB'))}`;
// The page opens on a menu of curricula, not on one course: the French levels (chapters on this site), then the other
// pathways (their pages), then the other ways in (slides, laboratory).
function curriculumMenu(t){const counts=Object.fromEntries(Object.keys(courses).map(id=>[id,resourceCatalog.chapters.filter(c=>c.course===id).length]));const resume=progress.last?resourceCatalog.chapters.find(c=>c.id===progress.last):null;const tile=(href,ic,title,meta)=>`<a class="menu-tile" href="${href}">${icon(ic,24)}<span><strong>${E(title)}</strong><span>${E(meta)}</span></span>${icon('caret-right',18)}</a>`;const pick=(id,ic,title,meta)=>`<button type="button" class="menu-tile" data-course="${id}">${icon(ic,24)}<span><strong>${E(title)}</strong><span>${E(meta)}</span></span>${icon('caret-right',18)}</button>`;
if(filter==='fr')return `<section class="menu-group"><h2>${t(P('Programme français · lycée','French curriculum · lycée'))}</h2><div class="menu-tiles">${Object.keys(courses).map(id=>pick(id,'books',t(courses[id]),`${counts[id]} ${t(P('chapitres','chapters'))}`)).join('')}</div></section>`;
return `${resume?`<a class="resume" href="#chapter/${resume.id}">${icon('clock-counter-clockwise',20)}<span><strong>${t(P('Reprendre','Continue'))}</strong> ${E(t(courses[resume.course]))} · ${E(t(resume.title))}</span>${icon('caret-right',18)}</a>`:''}<section class="menu-group"><h2>${t(P('Choisir un programme','Choose a curriculum'))}</h2><div class="menu-tiles">${pick('fr','books',t(P('Programme français','French curriculum')),t(P(`Seconde à Terminale · ${Object.values(counts).reduce((a,b)=>a+b,0)} chapitres`,`Seconde to Terminale · ${Object.values(counts).reduce((a,b)=>a+b,0)} chapters`)))}${tile('#pathways','path',t(P('Programme malgache','Malagasy curriculum')),t(P('Terminale S, OSE, L','Terminale S, OSE, L')))}${tile('#pathways','globe',t(P('International','International')),t(P('IB et SAT','IB and SAT')))}${tile('#university','graduation-cap',t(P('Université','University')),t(P('Bases du supérieur','Early-university foundations')))}</div></section><section class="menu-group"><h2>${t(P('Autres entrées','Other ways in'))}</h2><div class="menu-tiles">${tile('#slides','presentation-chart',t(P('Diaporamas','Slides')),t(P('Pour la classe, HTML et PDF','For the classroom, HTML and PDF')))}${tile('#workshop/quadratic','arrows-out',t(P('Trinôme en 5 étapes','Quadratics in 5 steps')),t(P('Présenter et explorer','Present and explore')))}${tile('#pack','stack',t(P('Dossier sur mesure','Custom pack')),t(P('Choisir ses chapitres','Pick your chapters')))}</div></section>${workshopCards(t)}`;}
const inMenu=()=>!query.trim()&&(!filter||filter==='fr');
function chapterPreview(c,t) {
 const item={...c,concepts:[c.topic],route:'#chapter/'+c.id,format:'chapter'};
 if(previewKind(item)!=='reading')return previewSVG(item,t);
 const scene=guides[c.topic]?.scene, spec=scenes[scene];
 if(!spec)return previewSVG(item,t);
 const illustration=diagram(scene,spec.range[3],2,t,n=>String(Math.round(n*100)/100));
 const svg=illustration.svg.replaceAll('lesson-clip','preview-'+c.id);
 return `<figure class="discovery-preview lesson-diagram" data-preview="chapter">${svg}</figure>`;
}
function cards(t){const search=!!query.trim();if(inMenu())return curriculumMenu(t);const scope=search?'all':filter;const found=matchingChapters(scope,query),extra=matchingSupplements(scope,query);const workshops=workshopCards(t);const groups=Object.entries(courses).filter(([id])=>[...found,...extra].some(c=>c.course===id));const parts=c=>t(P('Objectifs · recherche · cours · entraînement · bilan','Goals · investigation · lesson · practice · review'))+(c.files.some(f=>f.kind==='fluency')?' · '+t(P('automatismes','fluency')):'');const resume=!search&&progress.last?resourceCatalog.chapters.find(c=>c.id===progress.last):null;return `<p class="resource-count" role="status">${found.length} ${t(search?P('chapitres trouvés','chapters found'):P('chapitres','chapters'))}${search||!extra.length?'':` · ${extra.length} ${t(P('ressources de préparation','preparation resources'))}`}</p>${resume?`<a class="resume" href="#chapter/${resume.id}">${icon('clock-counter-clockwise',20)}<span><strong>${t(P('Reprendre','Continue'))}</strong> ${E(t(courses[resume.course]))} · ${E(t(resume.title))}</span>${icon('caret-right',18)}</a>`:''}${groups.map(([id,title])=>`<section class="course-group">${search?`<h2 class="group-title">${E(t(title))}</h2>`:''}<ol class="chapter-grid">${found.filter(c=>c.course===id).map(c=>{return `<li><a class="chapter-tile" data-chapter="${E(c.id)}" href="#chapter/${E(c.id)}">${chapterPreview(c,t)}<span class="chapter-tile-body"><strong>${E(t(c.title))}</strong><span>${E(t(guides[c.topic]?.idea||P('Consulter le chapitre et ses documents.','Open the chapter and its documents.')))}</span><small>${E(t(P('Chapitre','Chapter')))} ${c.number} · PDF</small></span></a></li>`;}).join('')}</ol>${supplementCards(extra.filter(c=>c.course===id),t)}</section>`).join('')}${workshops}${found.length||extra.length||workshops?'':`<div class="resource-empty"><p>${t(P('Aucune ressource ne correspond à cette recherche.','No resources match this search.'))}</p><button data-clear-search>${t(P('Effacer la recherche','Clear the search'))}</button></div>`}`;}
export function libraryPage(t,{challenges=[],completed=new Set(),seen=new Set(),last='',labs=[]}={}){documentLanguage=t(P('fr','en'));progress.seen=seen;progress.last=last;const counts=Object.fromEntries(Object.keys(courses).map(id=>[id,resourceCatalog.chapters.filter(c=>c.course===id).length]));return `<main id="main" tabindex="-1" class="page resource-page home">
<div class="home-head"><h1>${t(P('Cours et exercices','Lessons and exercises'))}</h1><p>${t(P('Choisis ton programme, puis ton niveau. Chaque chapitre : préparer ses acquis, chercher, construire le cours et s’entraîner.','Choose your curriculum, then your level. Each chapter: prepare, investigate, build the lesson and practise.'))}</p></div>
<div class="finder${inMenu()?' is-menu':''}"><section class="chooser" aria-label="${t(P('Choisir un chapitre','Choose a chapter'))}"><div class="chooser-tools"><button type="button" class="menu-back" data-menu-back ${filter?'':'hidden'}>${icon('caret-left',18)}${t(P('Retour','Back'))}</button><div class="segmented" role="group" aria-label="${t(P('Niveau','Level'))}" ${inMenu()?'hidden':''}>${Object.keys(tabLabels).map(id=>`<button class="seg" data-course="${id}" aria-pressed="${filter===id}">${t(tabLabels[id])}<span>${counts[id]}</span></button>`).join('')}</div><label class="search"><span class="sr-only">${t(P('Rechercher un chapitre','Find a chapter'))}</span>${icon('magnifying-glass',20)}<input id="resource-search" type="search" value="${E(query)}" placeholder="${t(P('Rechercher : suites, logarithme, probabilités…','Search: sequences, logarithm, probability…'))}"></label></div><div id="resource-results">${cards(t)}</div></section></div>
<details class="resource-origin"><summary>${t(P('D’où viennent ces ressources ?','Where do these resources come from?'))}</summary><p>${t(P('Les langues disponibles sont indiquées pour chaque document. Les guides essentiels et graphiques accompagnent chaque chapitre.','Available languages are listed for each document. Essential guides and diagrams accompany each chapter.'))}</p></details></main>`;}
export function bindLibrary(t) {
 const results=document.querySelector('#resource-results');
 const search=document.querySelector('#resource-search');
 const choose=id=>{filter=id;query='';search.value='';paint();};
 const paint=()=>{
  const menu=inMenu();results.innerHTML=cards(t);
  document.querySelector('.finder').classList.toggle('is-menu',menu);
  document.querySelector('.segmented').hidden=menu;
  document.querySelector('[data-menu-back]').hidden=!filter;
  document.querySelectorAll('.seg').forEach(b=>b.setAttribute('aria-pressed',String(!query.trim()&&b.dataset.course===filter)));
 };
 const click=e=>{const button=e.target.closest('[data-course],[data-clear-search]');if(!button)return;
  if(button.hasAttribute('data-course'))choose(button.dataset.course);
  else {query='';search.value='';paint();search.focus();}
 };
 const input=()=>{query=search.value;paint();};
 const back=()=>choose(filter&&filter!=='fr'?'fr':'');
 const root=document.querySelector('.chooser');root.addEventListener('click',click);
 search.addEventListener('input',input);document.querySelector('[data-menu-back]').addEventListener('click',back);paint();
 return ()=>{root.removeEventListener('click',click);search.removeEventListener('input',input);};
}
let documentLanguage='fr';
const t0=x=>x[documentLanguage==='en'?1:0];
const fileLink=(f,label,page=1)=>{if(!f)return '';const language=courseLanguage(resourceCatalog.chapters.find(c=>c.files.includes(f))?.course,documentLanguage),edition=editionFor(f,language);if(!edition)return `<p class="resource-note">${E(label)} · ${t0(P('Édition indisponible dans cette langue','Edition unavailable in this language'))}</p>`;return `<a class="document-link" href="./${assetHref(edition.path.replace(/^\.\//,''))}#page=${page}" target="_blank" rel="noopener">${E(label)} <span>PDF · ${edition.pages} p. · ${kb(edition.bytes,t0)}</span></a>`;};
function documentCards(c,t){return c.files.map(f=>{const source=resourceCatalog.sources.find(s=>s.name===f.source);const teacher=f.kind==='teacher'||f.kind==='fluency-solutions';const links=Object.entries(f.sections||{}).filter(([k])=>['lesson','practice','problem','quiz'].includes(k)).map(([k,p])=>fileLink(f,t({lesson:P('Cours / activités','Lessons / activities'),practice:P('Exercices','Exercises'),problem:P('Problèmes','Problems'),quiz:P('QCM','Multiple choice')}[k]),p)).join('');const label=t(kinds[f.kind])+(f.title?' · '+t(f.title):'');const body=`${fileLink(f,label)}${links?`<div class="section-links">${links}</div>`:''}<p class="document-meta">${t(P('Pages du document source','Source document pages'))} ${f.start}–${f.end} · ${t(P('Modifié le','Modified'))} ${source.modified.slice(0,10)}</p>`;return teacher?`<details class="document-card"><summary>${E(label)}</summary>${body}</details>`:`<article class="document-card">${body}</article>`;}).join('');}
function sourcePractice(c,t){const f=c.files.find(f=>f.kind==='chapter');return `<div class="source-practice"><h2>${t(P('Poursuivre dans ton livret','Continue in your booklet'))}</h2><p>${t(P('Le chapitre complet contient les activités et les exercices de ton niveau. Certaines pages mêlent cours et entraînement.','The full chapter contains activities and exercises for your course. Some pages combine lessons and practice.'))}</p>${fileLink(f,t(P('Ouvrir les exercices du chapitre','Open the chapter exercises')),f.sections?.practice||1)}<details><summary>${t(P('Consulter la version professeur après avoir cherché','Read the teacher version after trying'))}</summary>${fileLink(c.files.find(f=>f.kind==='teacher'),t(P('Corrections et conseils','Solutions and guidance')))}</details></div>`;}
export function chapterPage(id,tab,t,labs){const c=resourceCatalog.chapters.find(c=>c.id===id);return chapterSequencePage(c,tab,t,resourceCatalog.chapters);}
export function bindChapter(id,t,fmt){return mountChapterSequence(resourceCatalog.chapters.find(c=>c.id===id),t);}
export function relatedChapters(labId,t){const related=resourceCatalog.chapters.filter(c=>guides[c.topic]?.lab===labId);return related.length?`<details class="related-chapters"><summary>${t(P('Cours et exercices liés','Related lessons and exercises'))}</summary><div>${related.map(c=>`<a href="#chapter/${c.id}">${E(t(courses[c.course]))} · ${E(t(c.title))}</a>`).join('')}</div></details>`:'';}
